import RNA
import random

target = '.((.((.((.((..((..((.((...))..)).)).))..))....)).'
n = len(target)
fc = RNA.fold_compound(target)

# precompute target pairs
pairs = [None]*n
stack=[]
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[i]=j; pairs[j]=i

def parse_db(s):
    pr=[None]*len(s); st=[]
    for i,c in enumerate(s):
        if c=='(':
            st.append(i)
        elif c==')':
            j=st.pop(); pr[i]=j; pr[j]=i
    return pr

def bp_dist(s):
    pr=parse_db(s)
    d=0
    for i in range(n):
        a = pr[i] if pr[i] is not None else -1
        b = pairs[i] if pairs[i] is not None else -1
        if a!=b:
            d+=1
    return d//2

# initialize: complementary at pairs, random at unpaired
def rand_init():
    seq=['A']*n
    for i in range(n):
        if pairs[i] is not None and i<pairs[i]:
            # choose pair type
            choice=random.choice(['GC','CG','AU','UA','GU','UG'])
            seq[i]=choice[0]; seq[pairs[i]]=choice[1]
    for i in range(n):
        if pairs[i] is None:
            seq[i]=random.choice('ACGU')
    return ''.join(seq)

best=None; best_d=999
import sys
random.seed(int(sys.argv[1]) if len(sys.argv)>1 else 0)

for it in range(200000):
    if best_d==0:
        break
    if best is None or it%5000==0:
        # perturb from best or fresh
        if best is None:
            seq=rand_init()
        else:
            s=list(best)
            # mutate a few
            for _ in range(random.randint(1,4)):
                i=random.randrange(n)
                s[i]=random.choice('ACGU')
            seq=''.join(s)
    else:
        s=list(best)
        # targeted: fold, find spurious pairs, break them
        mfe,_=RNA.fold(seq)
        pr=parse_db(mfe)
        spurious=[]
        for i in range(n):
            if pr[i] is not None and (pairs[i] is None or pr[i]!=pairs[i]):
                spurious.append(i)
        for i in spurious:
            if random.random()<0.5:
                s[i]=random.choice('ACGU')
                if pr[i] is not None and pr[i]<n:
                    if random.random()<0.3:
                        s[pr[i]]=random.choice('ACGU')
        # also strengthen missing pairs
        missing=[]
        for i in range(n):
            if pairs[i] is not None and (pr[i] is None or pr[i]!=pairs[i]):
                missing.append(i)
        for i in missing:
            if random.random()<0.5:
                j=pairs[i]
                s[i]='G'; s[j]='C'
        seq=''.join(s)
    d=bp_dist(RNA.fold(seq)[0])
    if d<best_d:
        best_d=d; best=seq
        print('iter',it,'d',d, seq, flush=True)
        if d==0:
            break

print('BEST', best, best_d)
